<script lang="ts">
  import { pokePelago } from '../stores/pokePelago.svelte.ts';
  import type { PokePelagoIslandId } from '../lib/pokePelagoLogic.ts';
  import {
    capPelagoPredictedPending,
    getPelagoStorageProgress,
    rewardBarClaimDisplay,
    rewardBarClaimFraction,
    rewardBarStack,
  } from '../lib/pokePelagoLogic.ts';
  import { game } from '../../gameManager.ts';
  import { ui as uiStore } from '../stores/ui.svelte.ts';
  import { showFloatingText } from '../ui/floatingText.ts';
  import { hideGameTooltip, touchTooltipHandlers } from '../ui/scheduleTooltipHelpers.ts';
  import PokePelagoAssignPicker from './PokePelagoAssignPicker.svelte';

  let snap = $derived(pokePelago.snapshot);
  let ui = $derived(snap.ui);
  let pelagoModalOpen = $derived(uiStore.openModals.has('pokePelagoModal'));
  let claimToast = $state<string | null>(null);
  let claimToastTimer: ReturnType<typeof setTimeout> | null = null;
  let smoothFills = $state<Record<string, number>>({});
  let smoothLabels = $state<Record<string, string>>({});
  /** Keys currently snapping (no CSS width transition / drain-to-zero). */
  let smoothSnapKeys = $state<Record<string, boolean>>({});

  let confirmingUnassignIslandId = $state<string | null>(null);
  let confirmingTimer: ReturnType<typeof setTimeout> | null = null;

  function pelagoTip(getContent: () => { title: string; body?: string }) {
    const inner = touchTooltipHandlers(getContent);
    const showIf = (e: MouseEvent | FocusEvent) => {
      const { title, body = '' } = getContent();
      if (!title && !body) return;
      inner.onmouseenter(e);
    };
    return {
      ...inner,
      onmouseenter: showIf,
      onfocus: showIf,
    };
  }

  function hoverTip(getContent: () => { title: string; body?: string }) {
    const inner = touchTooltipHandlers(getContent);
    const showIf = (e: MouseEvent | FocusEvent) => {
      const { title, body = '' } = getContent();
      if (!title && !body) return;
      inner.onmouseenter(e);
    };
    return {
      onmouseenter: showIf,
      onmouseleave: inner.onmouseleave,
      onfocus: showIf,
      onblur: inner.onblur,
    };
  }

  $effect(() => {
    if (!pelagoModalOpen) hideGameTooltip();
  });

  const FILL_DRAIN_MS = 100;
  const FILL_DROP_EPS = 0.04;

  type SmoothAnchor = { pending: number; ratePerHour: number; at: number };
  type DrainState = { startedAt: number };
  const smoothAnchors = new Map<string, SmoothAnchor>();
  const drainStates = new Map<string, DrainState>();
  const displayedFills = new Map<string, number>();

  const RARE_ITEM_KEYS = new Set([
    'proteine',
    'protein',
    'calcium',
    'moomoo_milk',
    'oran_berry',
    'baie_oran',
    'rare_candy',
    'full_restore',
  ]);

  function isItemRare(key: string): boolean {
    return RARE_ITEM_KEYS.has(key);
  }

  function formatPelagoNumber(n: number | null | undefined): string {
    if (n == null || !Number.isFinite(n)) return '0';
    if (n >= 1e6 || (n > 0 && n < 0.001)) {
      return n.toExponential(2).replace('+', '');
    }
    return Math.floor(n).toLocaleString(game?.language === 'en' ? 'en-US' : 'fr-FR');
  }

  function formatRateVal(rate: number | null | undefined): string {
    if (rate == null || !(rate > 0)) return '0';
    if (rate >= 10) {
      return Math.round(rate).toLocaleString(game?.language === 'en' ? 'en-US' : 'fr-FR');
    }
    return rate.toFixed(1);
  }

  let levelXpPct = $derived(
    snap.isMaxLevel
      ? 100
      : snap.xpPerLevel > 0
        ? Math.min(100, Math.max(0, (snap.xpTowardNextLevel / snap.xpPerLevel) * 100))
        : 0,
  );

  function getStorageProgress(island: typeof snap.islands[number]): { pct: number; hours: string } {
    return getPelagoStorageProgress(island);
  }

  function parsePityProgress(pityLabel: string | null): { current: number; need: number; pct: number } | null {
    if (!pityLabel) return null;
    const m = pityLabel.match(/(\d+)\s*[/:]\s*(\d+)/);
    if (!m) return null;
    const current = parseInt(m[1], 10);
    const need = parseInt(m[2], 10);
    const pct = need > 0 ? Math.min(100, Math.round((current / need) * 100)) : 0;
    return { current, need, pct };
  }

  function getMasteryProgress(island: typeof snap.islands[number]): { currentStr: string; needStr: string; pct: number } {
    if (island.isMaxMastery) {
      return { currentStr: ui.levelMax || 'Niveau max', needStr: '', pct: 100 };
    }
    const xp = island.masteryXp || 0;
    const need = island.masteryXpPerLevel || 0;
    const pct = need > 0 ? Math.min(100, (xp / need) * 100) : 0;
    return {
      currentStr: formatPelagoNumber(xp),
      needStr: formatPelagoNumber(need),
      pct,
    };
  }

  function formatSmoothLabel(rowId: string, snapshotPending: number, predicted: number): string {
    const tplUi = pokePelago.snapshot.ui;
    const capped = capPelagoPredictedPending(snapshotPending, predicted);
    const stack = rewardBarStack(snapshotPending);
    const digits = rowId === 'xp' ? 1 : 2;
    // Honest vs claim gate (floor ≥ 1) — not ×N micro-cycle fill.
    const current = rewardBarClaimDisplay(capped, digits);
    const replace = (tpl: string) =>
      tpl.replaceAll('{stack}', String(stack)).replaceAll('{current}', current);
    if (stack >= 1) {
      if (rowId === 'shards') return replace(tplUi.progressShardsStacked);
      if (rowId === 'beans') return replace(tplUi.progressBeansStacked);
      if (rowId === 'prestige') return replace(tplUi.progressPrestigeStacked);
      if (rowId === 'xp') return replace(tplUi.progressXpStacked);
    } else {
      if (rowId === 'shards') return replace(tplUi.progressShards);
      if (rowId === 'beans') return replace(tplUi.progressBeans);
      if (rowId === 'prestige') return replace(tplUi.progressPrestige);
      if (rowId === 'xp') return replace(tplUi.progressXp);
      if (rowId === 'items') return replace(tplUi.progressItems);
    }
    return '';
  }

  function resolveDisplayFill(key: string, targetFill: number, now: number): { fill: number; snap: boolean } {
    const prev = displayedFills.get(key);
    const drain = drainStates.get(key);
    if (drain) {
      if (now - drain.startedAt >= FILL_DRAIN_MS) {
        drainStates.delete(key);
        displayedFills.set(key, targetFill);
        return { fill: targetFill, snap: true };
      }
      displayedFills.set(key, 0);
      return { fill: 0, snap: true };
    }
    if (prev != null && targetFill < prev - FILL_DROP_EPS) {
      drainStates.set(key, { startedAt: now });
      displayedFills.set(key, 0);
      return { fill: 0, snap: true };
    }
    displayedFills.set(key, targetFill);
    return { fill: targetFill, snap: false };
  }

  $effect(() => {
    // Modal stays mounted after first open — stop rAF while closed.
    if (!pelagoModalOpen) return;

    let rafId = 0;
    const tick = () => {
      const s = pokePelago.snapshot;
      const now = Date.now();
      const syncedAt = s.syncedAt;
      const nextFills: Record<string, number> = {};
      const nextLabels: Record<string, string> = {};
      const nextSnap: Record<string, boolean> = {};
      const seen = new Set<string>();
      for (const island of s.islands) {
        for (const row of island.progressRows) {
          if (row.ratePerHour == null || !(row.ratePerHour > 0) || row.pending == null) continue;
          const key = `${island.id}:${row.id}`;
          seen.add(key);
          const prev = smoothAnchors.get(key);
          let anchor: SmoothAnchor;
          if (prev && prev.ratePerHour === row.ratePerHour && prev.pending === row.pending) {
            // Unchanged — keep interpolating from the existing anchor.
            anchor = prev;
          } else if (prev && prev.ratePerHour === row.ratePerHour && row.pending > prev.pending) {
            // Soft re-anchor on pending grant: predicted ≈ new pending, so no visual jump.
            anchor = { pending: row.pending, ratePerHour: row.ratePerHour, at: now };
          } else {
            // Claim (pending drop), rate change, or first sight — hard reset.
            anchor = { pending: row.pending, ratePerHour: row.ratePerHour, at: syncedAt };
          }
          if (anchor !== prev) smoothAnchors.set(key, anchor);
          const predicted =
            anchor.pending + (anchor.ratePerHour * Math.max(0, now - anchor.at)) / 3_600_000;
          const capped = capPelagoPredictedPending(row.pending, predicted);
          const targetFill = rewardBarClaimFraction(capped);
          const resolved = resolveDisplayFill(key, targetFill, now);
          nextFills[key] = resolved.fill;
          nextSnap[key] = resolved.snap;
          nextLabels[key] = formatSmoothLabel(row.id, row.pending, predicted);
        }
      }
      for (const key of smoothAnchors.keys()) {
        if (!seen.has(key)) smoothAnchors.delete(key);
      }
      for (const key of drainStates.keys()) {
        if (!seen.has(key)) drainStates.delete(key);
      }
      for (const key of displayedFills.keys()) {
        if (!seen.has(key)) displayedFills.delete(key);
      }
      smoothFills = nextFills;
      smoothLabels = nextLabels;
      smoothSnapKeys = nextSnap;
      rafId = requestAnimationFrame(tick);
    };
    rafId = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(rafId);
  });

  function showClaimToast(msg?: string): void {
    claimToast = msg || ui.claimToast;
    if (claimToastTimer) clearTimeout(claimToastTimer);
    claimToastTimer = setTimeout(() => {
      claimToast = null;
      claimToastTimer = null;
    }, 1800);
  }

  function levelAbbrev(level: number | null): string {
    if (level == null) return '';
    const tpl = ui.levelAbbrev || 'Lv.{level}';
    if (tpl.includes('{level}')) return tpl.replaceAll('{level}', String(level));
    const trimmed = tpl.replace(/\s+$/, '');
    return `${trimmed}${level}`;
  }

  function rowRate(island: (typeof snap.islands)[number], rowId: string): number | null {
    const rate = island.progressRows.find((row) => row.id === rowId)?.ratePerHour;
    return rate != null && rate > 0 ? rate : null;
  }

  function resourceName(label: string): string {
    return label.replace(/\s*\([^)]*\)/g, '').trim();
  }

  function handleUnassignClick(islandId: PokePelagoIslandId): void {
    if (confirmingUnassignIslandId !== islandId) {
      confirmingUnassignIslandId = islandId;
      if (confirmingTimer) clearTimeout(confirmingTimer);
      confirmingTimer = setTimeout(() => {
        confirmingUnassignIslandId = null;
        confirmingTimer = null;
      }, 3000);
      return;
    }
    if (confirmingTimer) {
      clearTimeout(confirmingTimer);
      confirmingTimer = null;
    }
    confirmingUnassignIslandId = null;
    unassign(islandId);
  }

  function claim(islandId: PokePelagoIslandId, event?: MouseEvent): void {
    const island = snap.islands.find((i) => i.id === islandId);
    let summary = '';
    if (island) {
      if (island.id === 'abeens') {
        summary = `+${formatPelagoNumber(island.pendingShards)} ${game?.language === 'en' ? 'shards' : 'éclats'}`;
      } else if (island.id === 'evelup') {
        summary = `+${formatPelagoNumber(island.pendingXp)} XP`;
      } else if (island.id === 'aphun') {
        const cnt = island.pendingItems.reduce((acc, it) => acc + it.qty, 0);
        summary = `+${cnt} ${game?.language === 'en' ? 'items' : 'objets'}`;
      }
    }
    const ok = game?.claimPokePelagoIsland?.(islandId);
    if (ok) {
      showClaimToast(summary || ui.claimToast);
      if (event?.currentTarget instanceof HTMLElement) {
        showFloatingText({ text: summary || '+Récolte' }, event.currentTarget, 'ft-heal');
      }
    }
  }

  function claimAll(event?: MouseEvent): void {
    const ok = game?.claimAllPokePelago?.();
    if (ok) {
      showClaimToast(ui.claimToast);
      if (event?.currentTarget instanceof HTMLElement) {
        showFloatingText({ text: '+Tout récolté' }, event.currentTarget, 'ft-heal');
      }
    }
  }

  function unassign(islandId: PokePelagoIslandId): void {
    game?.assignPokePelago?.(islandId, null, 'storage', 0);
  }
</script>

<div class="poke-pelago-modal-inner">
  <div class="poke-pelago-hud-grid">
    <div
      class="poke-pelago-hud-tile poke-pelago-hud-tile--level"
      {...pelagoTip(() => ({
        title: '',
        body: [
          snap.isMaxLevel
            ? (ui.levelMax || '')
            : `${formatPelagoNumber(snap.xpTowardNextLevel)} / ${formatPelagoNumber(snap.xpPerLevel)}`,
          snap.beansHint || '',
        ].filter(Boolean).join('<br>'),
      }))}
    >
      <span class="poke-pelago-hud-label">PELAGO</span>
      <span class="poke-pelago-hud-val">{levelAbbrev(snap.level)}</span>
      <span class="poke-pelago-hud-pct">({Math.floor(levelXpPct)}%)</span>
      {#if snap.isMaxLevel}
        <span class="poke-pelago-hud-sub">{ui.levelMax || 'Niveau max'}</span>
      {:else}
        <div class="poke-pelago-hud-xp-val-row">
          <span class="poke-pelago-hud-xp-num">{formatPelagoNumber(snap.xpTowardNextLevel)}</span>
          <span class="poke-pelago-hud-xp-denom">/ {formatPelagoNumber(snap.xpPerLevel)}</span>
        </div>
      {/if}
      <div
        class="poke-pelago-hud-bar"
        role="progressbar"
        aria-valuenow={Math.round(levelXpPct)}
        aria-valuemin={0}
        aria-valuemax={100}
        aria-label="XP Pelago"
      >
        <div class="poke-pelago-hud-bar-fill" style="width: {levelXpPct}%"></div>
      </div>
    </div>

    <div class="poke-pelago-hud-tile">
      <span class="poke-pelago-hud-label">PRODUCTION</span>
      <span class="poke-pelago-hud-mobile-prefix">Prod:</span>
      <span
        class="poke-pelago-hud-val poke-pelago-hud-val--green"
        {...pelagoTip(() => ({
          title: snap.prodSourcesTooltipTitle,
          body: snap.prodSourcesTooltipBody,
        }))}
      >
        +{snap.levelBonusPercent.toLocaleString(game?.language === 'en' ? 'en-US' : 'fr-FR')}%
      </span>
      <span class="poke-pelago-hud-sub">{game?.language === 'en' ? 'All isles bonus' : 'Toutes îles'}</span>
    </div>

    <div
      class="poke-pelago-hud-tile"
      {...pelagoTip(() => ({ title: '', body: ui.offlineCapHint || '' }))}
    >
      <span class="poke-pelago-hud-label">MAX</span>
      <span class="poke-pelago-hud-mobile-prefix">Max:</span>
      <span class="poke-pelago-hud-val">48<span class="poke-pelago-hud-unit">h</span></span>
    </div>
  </div>

  <!-- TOAST / NOTIFICATIONS -->
  {#if claimToast}
    <div class="poke-pelago-claim-toast" role="status" aria-live="polite">
      <span class="poke-pelago-toast-icon">✨</span> {claimToast}
    </div>
  {/if}

  {#if snap.evelupBanner}
    <div class="poke-pelago-evelup-banner" role="status">
      <span class="poke-pelago-banner-icon">💎</span> {snap.evelupBanner}
    </div>
  {/if}

  <!-- BANDEAU ÎLES & BOUTON TOUT RÉCLAMER (STICKY) -->
  <div class="poke-pelago-section-bar">
    <div class="poke-pelago-section-tag">
      {game?.language === 'en' ? 'ISLES' : 'ÎLES'} ({snap.islands.length})
    </div>
    {#if snap.claimableCount > 0}
      <button
        type="button"
        class="poke-pelago-btn-primary poke-pelago-claim-all-btn"
        onclick={(e) => claimAll(e)}
      >
        {ui.claimAll} ({snap.claimableCount})
      </button>
    {:else}
      <button
        type="button"
        class="poke-pelago-btn-secondary poke-pelago-claim-all-btn"
        disabled
      >
        {ui.claimAll}
      </button>
    {/if}
  </div>

  <!-- LISTE DES ÎLES -->
  <div class="poke-pelago-islands-list">
    {#each snap.islands as island (island.id)}
      {@const mastery = getMasteryProgress(island)}
      <div
        class="poke-pelago-island-card"
        class:island-locked={!island.unlocked}
        class:island-claimable={island.claimable}
        class:island-unassigned={island.unlocked && !island.assignedUid}
      >
        <!-- EN-TÊTE DE CARTE AVEC MAÎTRISE INTÉGRÉE -->
        <div class="poke-pelago-island-header">
          <div class="poke-pelago-island-header-left">
            <div class="poke-pelago-island-title-row">
              <h3 class="poke-pelago-island-name">{island.name}</h3>
              {#if island.masteryLabel}
                <span
                  class="poke-pelago-chip poke-pelago-chip--gold"
                  {...pelagoTip(() => ({ title: '', body: ui.masteryChipHint || '' }))}
                >
                  {island.masteryLabel}
                </span>
                {#if island.masteryBonusLabel}
                  <span
                    class="poke-pelago-chip poke-pelago-chip--bonus"
                    {...pelagoTip(() => ({ title: '', body: ui.masteryBonusHint || island.masteryBonusLabel || '' }))}
                  >
                    {island.masteryBonusLabel}
                  </span>
                {/if}
              {/if}
            </div>
            <!-- Fine barre de progression de maîtrise intégrée au header -->
            {#if island.masteryXpPerLevel > 0}
              <div
                class="poke-pelago-mastery-mini-bar"
                {...pelagoTip(() => ({
                  title: '',
                  body: island.isMaxMastery
                    ? (ui.levelMax || 'Niveau max')
                    : (island.masteryProgressLabel || `${game?.language === 'en' ? 'Mastery XP' : 'Maîtrise XP'} : ${mastery.currentStr} / ${mastery.needStr} (${Math.round(mastery.pct)}%)`),
                }))}
              >
                <div class="poke-pelago-mastery-mini-fill" style="width: {mastery.pct}%"></div>
              </div>
            {/if}
          </div>
          <span class="poke-pelago-role-tag">{island.role}</span>
        </div>

        <!-- CONTENU CARTE -->
        {#if !island.unlocked}
          <!-- ÉTAT VERROUILLÉ (CRISTAUX Z) -->
          <div class="poke-pelago-locked-box">
            <span class="poke-pelago-locked-icon">🔒</span>
            <div class="poke-pelago-locked-meta">
              <strong class="poke-pelago-locked-title">{island.name} — {ui.lockedGeneric || 'Verrouillée'}</strong>
              <p class="poke-pelago-locked-desc">{island.unlockHint ?? ui.lockedGeneric}</p>
            </div>
          </div>
        {:else}
          <div class="poke-pelago-island-body" class:is-empty={!island.assignedUid}>
            <div class="poke-pelago-col poke-pelago-col--meta">
              {#if island.assignedUid}
                <div class="poke-pelago-slot-row">
                  <PokePelagoAssignPicker
                    islandId={island.id}
                    islandName={island.name}
                    candidates={snap.candidates}
                    {ui}
                    customClass="poke-pelago-slot-picker"
                  >
                    <div
                      class="poke-pelago-slot-box"
                      {...(island.assigneeTooltipTitle
                        ? hoverTip(() => ({
                            title: island.assigneeTooltipTitle ?? '',
                            body: island.assigneeTooltipBody ?? '',
                          }))
                        : {})}
                    >
                      {#if island.assignedSpriteUrl}
                        <img
                          class="poke-pelago-slot-sprite"
                          src={island.assignedSpriteUrl}
                          alt=""
                          width="48"
                          height="48"
                          loading="lazy"
                          decoding="async"
                        />
                      {/if}
                      <div class="poke-pelago-slot-info">
                        <div class="poke-pelago-slot-name-row">
                          <strong class="poke-pelago-slot-name">{island.assignedName}</strong>
                          <span class="poke-pelago-slot-swap" aria-hidden="true">⇄</span>
                        </div>
                        <span class="poke-pelago-slot-sub">
                          <span class="poke-pelago-slot-lvl">{levelAbbrev(island.assignedLevel)}</span>
                          {#if island.assigneeBonusLabel}
                            <span class="poke-pelago-slot-bonus"> · {island.assigneeBonusLabel}</span>
                          {/if}
                        </span>
                      </div>
                    </div>
                  </PokePelagoAssignPicker>
                  <button
                    type="button"
                    class="poke-pelago-slot-remove"
                    class:confirming={confirmingUnassignIslandId === island.id}
                    aria-label={confirmingUnassignIslandId === island.id
                      ? (game?.language === 'en' ? 'Confirm?' : 'Confirmer ?')
                      : ui.unassign}
                    onclick={(e) => {
                      e.stopPropagation();
                      handleUnassignClick(island.id);
                    }}
                  >✕</button>
                </div>
                {#if island.offlineHint || island.poolHint}
                  <div class="poke-pelago-rates-box">
                    {#if island.offlineHint}
                      <div class="poke-pelago-offline-line">
                        <span class="rate-icon">⏱</span>
                        <span>{island.offlineHint}</span>
                      </div>
                    {/if}
                    {#if island.poolHint}
                      <div
                        class="poke-pelago-pool-line"
                        {...pelagoTip(() => ({ title: '', body: island.poolHint || '' }))}
                      >
                        <span class="rate-icon">🎁</span>
                        <span>{island.poolHint}</span>
                      </div>
                    {/if}
                  </div>
                {/if}
              {:else}
                <PokePelagoAssignPicker
                  islandId={island.id}
                  islandName={island.name}
                  candidates={snap.candidates}
                  {ui}
                  customClass="poke-pelago-slot-picker"
                >
                  <div class="poke-pelago-slot-box slot-empty">
                    <span class="poke-pelago-slot-empty-hint">{ui.rateIdle} {island.role}</span>
                  </div>
                </PokePelagoAssignPicker>
              {/if}
            </div>

            {#if island.assignedUid || island.claimable}
            <div class="poke-pelago-col poke-pelago-col--harvest">
              <div class="poke-pelago-harvest-header">
                <span class="poke-pelago-harvest-status" class:status-ready={island.claimable}>
                  {#if island.claimable}
                    <span class="poke-pelago-status-dot dot-ready">●</span> {ui.etaReady || 'Prêt à réclamer'}
                  {:else}
                    <span class="poke-pelago-status-dot dot-busy">○</span> {island.etaLabel || (game?.language === 'en' ? 'Producing…' : 'En production…')}
                  {/if}
                </span>
              </div>

              <!-- JAUGE UNIQUE DE REMPLISSAGE DU STOCKAGE (48H) -->
              {#if island.assignedUid}
                {@const storage = getStorageProgress(island)}
                <div class="poke-pelago-storage-gauge">
                  <div class="poke-pelago-storage-top">
                    <span class="poke-pelago-storage-title">
                      {storage.pct >= 100
                        ? (game?.language === 'en' ? 'Storage full' : 'Stockage plein')
                        : (game?.language === 'en' ? 'Storage' : 'Stockage')}
                    </span>
                    <span class="poke-pelago-storage-pct" class:is-full={storage.pct >= 100}>
                      {storage.pct}% {storage.pct >= 100 ? (game?.language === 'en' ? '(Full)' : '(Plein)') : `(${storage.hours} h)`}
                    </span>
                  </div>
                  <div
                    class="poke-pelago-storage-bar"
                    role="progressbar"
                    aria-valuenow={storage.pct}
                    aria-valuemin={0}
                    aria-valuemax={100}
