                  {@const shardsRate = rowRate(island, 'shards')}
                  {@const beansRate = rowRate(island, 'beans')}
                  {@const stonesRate = rowRate(island, 'prestige')}
                  <div class="poke-pelago-res-rows">
                    <div class="poke-pelago-res-row">
                      <div class="poke-pelago-res-left">
                        <span class="poke-pelago-res-dot dot-shards"></span>
                        <span class="poke-pelago-res-name">{resourceName(ui.productAbeensShards || 'Éclats d’espèce')}</span>
                        {#if shardsRate != null}<span class="poke-pelago-res-rate">(+{formatRateVal(shardsRate)}/h)</span>{/if}
                      </div>
                      <span
                        class="poke-pelago-res-val"
                        {...pelagoTip(() => ({ title: '', body: smoothLabels[`${island.id}:shards`] ?? '' }))}
                      >
                        {formatPelagoNumber(island.pendingShards)}
                      </span>
                    </div>

                    <div class="poke-pelago-res-row">
                      <div class="poke-pelago-res-left">
                        <span class="poke-pelago-res-dot dot-beans"></span>
                        <span class="poke-pelago-res-name">{resourceName(ui.productAbeensXp || 'XP Pelago')}</span>
                        {#if beansRate != null}<span class="poke-pelago-res-rate">(+{formatRateVal(beansRate)}/h)</span>{/if}
                      </div>
                      <span
                        class="poke-pelago-res-val"
                        {...pelagoTip(() => ({ title: '', body: smoothLabels[`${island.id}:beans`] ?? '' }))}
                      >
                        {formatPelagoNumber(island.pendingBeans)}
                      </span>
                    </div>

                    <div class="poke-pelago-res-row">
                      <div class="poke-pelago-res-left">
                        <span class="poke-pelago-res-dot dot-prestige"></span>
                        <span class="poke-pelago-res-name">{resourceName(ui.productAbeensPrestige || 'Pierres de Prestige')}</span>
                        {#if stonesRate != null}<span class="poke-pelago-res-rate">(+{formatRateVal(stonesRate)}/h)</span>{/if}
                      </div>
                      <span
                        class="poke-pelago-res-val"
                        {...pelagoTip(() => ({ title: '', body: smoothLabels[`${island.id}:prestige`] ?? '' }))}
                      >
                        {formatPelagoNumber(island.pendingPrestigeStones)}
                      </span>
                    </div>
                  </div>
                {:else if island.id === 'evelup'}
                  {@const xpRate = rowRate(island, 'xp')}
                  <div class="poke-pelago-res-rows">
                    <div class="poke-pelago-res-row">
                      <div class="poke-pelago-res-left">
                        <span class="poke-pelago-res-dot dot-xp"></span>
                        <span class="poke-pelago-res-name">{resourceName(ui.productEvelupXp || 'XP Pokémon')}</span>
                        {#if xpRate != null}<span class="poke-pelago-res-rate">(+{formatRateVal(xpRate)}/h)</span>{/if}
                      </div>
                      <span
                        class="poke-pelago-res-val"
                        {...pelagoTip(() => ({ title: '', body: smoothLabels[`${island.id}:xp`] ?? '' }))}
                      >
                        +{formatPelagoNumber(island.pendingXp)} XP
                      </span>
                    </div>
                  </div>
                {:else if island.id === 'aphun'}
                  <!-- GARANTIE RARE EN BARRE DORÉE SUR APHUN -->
                  {@const pity = parsePityProgress(island.pityLabel)}
                  {#if pity}
                    <div class="poke-pelago-pity-block">
                      <div class="poke-pelago-pity-header">
                        <span class="poke-pelago-pity-title">✦ {game?.language === 'en' ? 'Rare pity guarantee' : 'Garantie rare'}</span>
                        <span class="poke-pelago-pity-ratio">{pity.current} / {pity.need}</span>
                      </div>
                      <div class="poke-pelago-pity-bar" role="progressbar" aria-valuenow={pity.pct} aria-valuemin={0} aria-valuemax={100}>
                        <div class="poke-pelago-pity-fill" style="width: {pity.pct}%"></div>
                      </div>
                    </div>
                  {/if}

                  {@const itemsRate = rowRate(island, 'items')}
                  <div class="poke-pelago-res-rows">
                    <div class="poke-pelago-res-row">
                      <div class="poke-pelago-res-left">
                        <span class="poke-pelago-res-dot dot-items"></span>
                        <span class="poke-pelago-res-name">{resourceName(ui.productAphunItems || 'Objets accumulés')}</span>
                        {#if itemsRate != null}<span class="poke-pelago-res-rate">(+{formatRateVal(itemsRate)}/h)</span>{/if}
                      </div>
                      <span class="poke-pelago-res-val">
                        {island.pendingItems.reduce((acc, it) => acc + it.qty, 0).toLocaleString(game?.language === 'en' ? 'en-US' : 'fr-FR')}
                      </span>
                    </div>
                  </div>
                {/if}
              {/if}
            </div>
            {/if}
          </div>

          <!-- GRILLE D'OBJETS SUR TOUTE LA LARGEUR POUR APHUN -->
          {#if island.id === 'aphun' && island.pendingItems.length > 0}
            <div class="poke-pelago-item-grid-section">
              <div class="poke-pelago-item-grid-header">
                <span class="poke-pelago-item-grid-title">{game?.language === 'en' ? 'Harvestable items' : 'Objets à récolter'}</span>
                <span class="poke-pelago-item-grid-count">({island.pendingItems.length} {game?.language === 'en' ? 'types' : 'sortes'})</span>
              </div>
              <div class="poke-pelago-item-grid">
                {#each island.pendingItems as item (item.itemKey)}
                  <div
                    class="poke-pelago-item-chip"
                    class:item-chip--rare={isItemRare(item.itemKey)}
                    {...pelagoTip(() => ({ title: item.name, body: `×${item.qty}` }))}
                  >
                    <div class="poke-pelago-item-top">
                      {#if item.iconUrl}
                        <img
                          class="poke-pelago-item-icon item-sprite-img"
                          src={item.iconUrl}
                          alt=""
                          width="20"
                          height="20"
                          loading="lazy"
                          decoding="async"
                        />
                      {/if}
                      <span class="poke-pelago-item-name">{item.name}</span>
                    </div>
                    <b class="poke-pelago-item-qty">
                      ×{item.qty.toLocaleString(game?.language === 'en' ? 'en-US' : 'fr-FR')}
                    </b>
                  </div>
                {/each}
              </div>
            </div>
          {/if}

          {#if island.assignedUid || island.claimable}
            <div class="poke-pelago-actions">
              <button
                type="button"
                class={island.claimable ? 'poke-pelago-btn-primary' : 'poke-pelago-btn-secondary'}
                disabled={!island.claimable}
                onclick={(e) => claim(island.id, e)}
              >
                {ui.claim}
              </button>
            </div>
          {/if}
        {/if}
      </div>
    {/each}
  </div>
</div>

